    36|export function extractAppGeneratorSpecFromPrompt(prompt: string): AppGeneratorSpec | null {
    37|  const normalized = prompt.trim();
    38|
    39|  // Detect kind.
    40|  let kind: AppGeneratorSpec['kind'] = 'backend_service';
    41|  if (/\b(?:ios|mobile|expo|react\s+native|app\s+store)\b/i.test(normalized)) {
    42|    kind = 'expo_app';
    43|  } else if (/\b(?:web|website|dashboard|landing)\b/i.test(normalized)) {
    44|    kind = 'web_app';
    45|  } else if (/\bmodule\b/i.test(normalized)) {
    46|    kind = 'module';
    47|  } else if (/\b(?:backend|api|service|endpoint)\b/i.test(normalized)) {
    48|    kind = 'backend_service';
    49|  }
    50|
    51|  // Extract name: "called X", "named X", "for X", or fallback.
    52|  let name = '';
    53|  const calledMatch = normalized.match(/\b(?:called|named)\s+([a-zA-Z0-9_-]+)/i);
    54|  if (calledMatch) {
    55|    name = calledMatch[1];
    56|  } else {
    57|    const forMatch = normalized.match(/\b(?:for|app|module|service)\s+(?:called\s+|named\s+)?([a-zA-Z0-9_-]+)/i);
    58|    if (forMatch) {
    59|      name = forMatch[1];
    60|    }
    61|  }
    62|
    63|  // If no name found, try to use a keyword from the prompt.
    64|  if (!name) {
    65|    if (/build\s*metadata/i.test(normalized)) {
    66|      name = 'build-metadata';
    67|    } else if (/investor/i.test(normalized)) {
    68|      name = 'investor-tracker';
    69|    } else {
    70|      return null;
    71|    }
    72|  }
    73|
    74|  // Sanitize name: lowercase, replace spaces with hyphens.
    75|  name = name.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9_-]/g, '');
    76|
    77|  // Extract optional description.
    78|  const description = normalized.slice(0, 200);
    79|
    80|  // Extract optional features from the prompt.
    81|  const features: string[] = [];
    82|  if (/\bauth\b/i.test(normalized)) features.push('authentication');
    83|  if (/\b(?:crud|create|read|update|delete)\b/i.test(normalized)) features.push('crud_operations');
    84|  if (/\b(?:dashboard|admin)\b/i.test(normalized)) features.push('admin_dashboard');
    85|  if (/\b(?:notification|alert)\b/i.test(normalized)) features.push('notifications');
    86|  if (/\b(?:search|filter)\b/i.test(normalized)) features.push('search');
    87|  if (features.length === 0) features.push('core_functionality');
    88|
    89|  return { name, kind, description, features };
