   167|/**
   168| * Full chat-path handler: extract spec, generate blueprint, build answer.
   169| * Used by the IVX IA chat handler when route === 'app_generator'.
   170| */
   171|export function handleAppGeneratorChatRoute(prompt: string, generatorRegistered: boolean): AppGeneratorChatResult {
   172|  const spec = extractAppGeneratorSpecFromPrompt(prompt);
   173|
   174|  let blueprint: GeneratedAppBlueprint | null = null;
   175|  let blueprintError: string | null = null;
   176|
   177|  if (spec) {
   178|    const validation = validateAppSpec(spec);
   179|    if (validation.ok) {
   180|      try {
   181|        blueprint = generateApp(spec);
   182|      } catch (error) {
   183|        blueprintError = error instanceof Error ? error.message : 'Blueprint generation failed.';
   184|      }
   185|    } else {
   186|      blueprintError = validation.error ?? 'Invalid app spec.';
   187|    }
   188|  }
   189|
   190|  const answer = buildAppGeneratorChatAnswer(spec, blueprint, blueprintError, generatorRegistered);
