   590|/**
   591| * Register the Universal App Generator in the durable IVX tool registry, run a
   592| * real self-test (generate the sample blueprint + assert its validation passes),
   593| * record the test, enable it on pass, and record the run. Honest: the tool is
   594| * only enabled if the self-test actually passes.
   595| */
   596|export async function registerAndVerifyAppGeneratorTool(): Promise<AppGeneratorRegistration> {
   597|  const tool = await registerTool({
   598|    name: IVX_APP_GENERATOR_TOOL_NAME,
   599|    purpose: 'Generate a full app/module scaffold blueprint (architecture, frontend, backend, schema, tests, deployment plan) from a specification.',
   600|    permissions: ['read_only'],
   601|    riskLevel: 'low',
   602|    requiresApproval: false,
   603|    source: 'app_generator_bootstrap',
   604|  });
