   606|  const sample = generateApp(buildSampleSpec());
   607|  const selfTestPassed = sample.validation.passed && sample.fileCount > 0;
   608|
   609|  const report: ToolTestReport = {
   610|    passed: selfTestPassed,
   611|    overallLabel: selfTestPassed ? 'VERIFIED' : 'FAILED',
   612|    ranAt: new Date().toISOString(),
   613|    phases: [
   614|      {
   615|        phase: 'generate',
   616|        label: 'sample blueprint generation',
   617|        passed: sample.fileCount > 0,
   618|        detail: `Generated ${sample.fileCount} file(s) across frontend/backend/tests.`,
   619|      },
   620|      {
   621|        phase: 'validate',
   622|        label: 'blueprint validation gate',
   623|        passed: sample.validation.passed,
   624|        detail: sample.validation.summary,
   625|      },
   626|    ],
   627|  };
   628|
   629|  const tested = await recordToolTest(tool.id, report);
   630|  let finalTool = tested ?? tool;
   631|  if (selfTestPassed) {
   632|    const enabled = await setToolEnabled(finalTool.id, true);
   633|    finalTool = enabled ?? finalTool;
   634|    const ran = await recordToolRun(finalTool.id, `self-test VERIFIED: ${sample.appId} (${sample.fileCount} files)`);
   635|    finalTool = ran ?? finalTool;
   636|  }
   637|
   638|  return { tool: finalTool, sample, selfTestPassed };
